package com.kaycee.meritprep

import com.kaycee.meritprep.data.AssessmentQuestion

/**
 * Original Chemistry practice questions mapped to the JAMB topic identifiers.
 * These are authored practice items, not official JAMB or WAEC past questions.
 */
object ChemistryQuestionBank {
    private fun q(id: String, topic: String, prompt: String, options: List<String>, answer: Int, explanation: String) =
        AssessmentQuestion(id, topic, prompt, options, answer, explanation, "MeritPrep original Chemistry practice · $topic", false)

    val all: List<AssessmentQuestion> = listOf(
        q("chem-sep-001","chem-separation","Which method separates an insoluble solid from a liquid?",listOf("Filtration","Fractional distillation","Chromatography","Sublimation"),0,"Filtration retains the insoluble solid on a porous medium while the liquid passes through."),
        q("chem-sep-002","chem-separation","A mixture contains sand and sodium chloride. Which sequence can recover both substances?",listOf("Add water, filter, then crystallise the filtrate","Use a magnet, then distil the sand","Filter the dry mixture, then use chromatography","Sublime both substances"),0,"Salt dissolves in water but sand does not. Filtration separates sand; crystallisation recovers salt from the filtrate."),
        q("chem-sep-003","chem-separation","Which property is mainly used in fractional distillation of miscible liquids?",listOf("Different boiling behaviours","Different magnetic properties","Different particle colours","Different electrical charges"),0,"Fractional distillation separates miscible liquids by differences in volatility and boiling points."),
        q("chem-sep-004","chem-separation","A pure crystalline substance is heated at constant pressure. Which observation is commonly associated with a pure substance during melting?",listOf("A relatively sharp, constant melting temperature","A very broad melting range","Continuous production of a new gas","A permanent change in chemical composition"),0,"A pure substance generally melts over a narrow temperature range at a specified pressure."),
        q("chem-sep-005","chem-separation","Paper chromatography separates dye components because they:",listOf("Move at different rates between stationary and mobile phases","Have different nuclear charges","Are all converted into gases","Are separated by magnetic attraction"),0,"Different affinities for the stationary phase and solvent cause components to travel different distances."),
        q("chem-combination-001","chem-combination","Which statement expresses the law of conservation of mass?",listOf("Total mass remains constant in a closed chemical system","All reactions release heat","A compound always contains equal masses of its elements","Gas volume never changes during reaction"),0,"Atoms are rearranged in ordinary chemical reactions; total mass is conserved in a closed system."),
        q("chem-combination-002","chem-combination","How many moles are present in 9 g of water? (H = 1, O = 16)",listOf("0.25 mol","0.50 mol","1.0 mol","2.0 mol"),1,"Molar mass of water is 18 g mol⁻¹. Amount = 9 ÷ 18 = 0.50 mol."),
        q("chem-combination-003","chem-combination","What is the correct balanced equation for hydrogen reacting with oxygen to form water?",listOf("2H₂ + O₂ → 2H₂O","H₂ + O₂ → H₂O","H₂ + 2O₂ → H₂O","2H₂ + 2O₂ → H₂O"),0,"Two hydrogen molecules react with one oxygen molecule to form two water molecules; atom counts balance on both sides."),
        q("chem-combination-004","chem-combination","The coefficients in a balanced chemical equation represent:",listOf("Relative numbers of particles or moles","Relative atomic masses only","The reaction temperature","The charge on each atom"),0,"Balanced-equation coefficients give stoichiometric ratios of particles and moles."),
        q("chem-combination-005","chem-combination","What is the relative molecular mass of CO₂? (C = 12, O = 16)",listOf("28","32","44","48"),2,"Mr(CO₂) = 12 + (2 × 16) = 44."),
        q("chem-kinetic-gas-001","chem-kinetic-gas","Which statement best describes particles in a gas?",listOf("They move rapidly and randomly, far apart on average","They vibrate only at fixed positions","They are packed in a regular lattice","They cannot be compressed"),0,"Gas particles are widely spaced and move randomly, explaining flow and compressibility."),
        q("chem-kinetic-gas-002","chem-kinetic-gas","A gas occupies 300 cm³ at 100 kPa. At constant temperature its pressure becomes 150 kPa. What is its new volume?",listOf("200 cm³","300 cm³","450 cm³","600 cm³"),0,"Boyle's law: P₁V₁ = P₂V₂. V₂ = (100 × 300) ÷ 150 = 200 cm³."),
        q("chem-kinetic-gas-003","chem-kinetic-gas","Which temperature must be used in gas-law calculations?",listOf("Kelvin","Celsius","Fahrenheit","Any temperature scale"),0,"Gas-law proportionalities require absolute temperature in kelvin."),
        q("chem-kinetic-gas-004","chem-kinetic-gas","At constant pressure, the volume of a fixed amount of gas is directly proportional to its:",listOf("Absolute temperature","Density","Molar mass","Colour"),0,"Charles's law states that volume is directly proportional to kelvin temperature at constant pressure."),
