        q("chem-atomic-bonding-001","chem-atomic-bonding","An atom has atomic number 13 and mass number 27. How many neutrons does it contain?",listOf("13","14","27","40"),1,"Neutrons = mass number − atomic number = 27 − 13 = 14."),
        q("chem-atomic-bonding-002","chem-atomic-bonding","Which bond is formed by electrostatic attraction between oppositely charged ions?",listOf("Ionic","Covalent","Metallic","Hydrogen"),0,"Ionic bonding is the electrostatic attraction between positive and negative ions."),
        q("chem-atomic-bonding-003","chem-atomic-bonding","Which particle determines the atomic number of an element?",listOf("Proton","Neutron","Electron","Molecule"),0,"Atomic number is the number of protons in the nucleus."),
